        if r.get('Currency') and r.get('RateToTWD'):
            fx[r['Currency'].strip()] = Decimal(r['RateToTWD'].strip())
print('FX currencies:', fx)
if not fx:
    raise RuntimeError('No FX rates loaded')

# SAP downloads: Open + Closed are the non-Cancelled statuses exposed by SAP.
orders = []
for status in ['open','closed']:
    p = downloads / f'sap_orders_{status}_{PERIOD}.csv'
    if not p.exists():
        raise FileNotFoundError(p)
    part = read_csv(p)
