orders = [r for r in orders if FROM <= r['OrderDate'] <= TO and r['Status'] != 'Cancelled']
if any(r['Status'] == 'Cancelled' for r in orders):
    raise RuntimeError('Cancelled order included after filtering')

inv_path = downloads / f'sap_invoices_{PERIOD}.csv'
