    for c in [1,2,3,4,5,6]: set_text(sh.cell(row,c))
    summary[r['ProjectID']]['ApprovedExpenseTWD'] += amount_twd
    row += 1

# Quotes.
sh = wb['Quotes']; row = 5
for r in sorted(quotes, key=lambda x: (x.get('ProjectID',''), x.get('QuoteID',''))):
