    for c, v in enumerate(vals, 1): sh.cell(row, c, v)
    for c in [1,2,3,4,5,6,7]: set_text(sh.cell(row,c))
    summary[r['ProjectID']]['AcceptedQuoteTWD'] += amount_twd
    row += 1

# Summary, separate metrics. No order+quote revenue field is created.
sh = wb['Summary']; row = 5
for pid in sorted(summary):
    vals = [pid, summary[pid]['OrderTWD'], summary[pid]['InvoiceBalanceTWD'], summary[pid]['ApprovedExpenseTWD'], summary[pid]['AcceptedQuoteTWD']]
