    for c, v in enumerate(vals, 1): sh.cell(row, c, v)
    for c in [1,2,3,4]: set_text(sh.cell(row,c))
    row += 1

# Report sheet.
rep = wb['Report']
rep['B3'] = FROM
rep['D3'] = TO
rep['B4'] = 'SAP Sales Orders: Open/Closed only (non-Cancelled); SAP Invoices by invoice date; Expense Viewer: Approved only; quote_cli: Accepted only; integrated by ProjectID; FX from input/fx_rates.csv; orders and quotes are reported separately.'
rep['B5'] = now
rep['B7'] = 'Lab ERP SAP web; Expense Viewer desktop; quote_cli; fx_rates.csv'
rep['D7'] = now

